const crypto = require('crypto');
const path = '/n8n/automation-failures';
const data = $input.first().json;
const execution = data.execution || {};
const workflow = data.workflow || {};
// Raw error text can quote a payload, so only the node name leaves n8n. The full error stays in its execution history.
const node = String(execution.lastNodeExecuted || 'unknown node').slice(0, 100);
const message = `The step "${node}" failed.`;

console.log(`[automation failure] workflow="${workflow.name}" execution=${execution.id} node="${execution.lastNodeExecuted}"`);

const body = JSON.stringify({
  workflow: String(workflow.name || 'unknown').slice(0, 100),
  executionId: String(execution.id || 'unknown').slice(0, 100),
  message,
});
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto
  .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
  .update(`v1:${timestamp}:POST:${path}:${body}`)
  .digest('hex');
return [{ json: { url: `${$env.LENDLOOP_CONVEX_SITE_URL}${path}`, body, timestamp, signature: `v1=${signature}` } }];
